		cfg.InviteTTL = defaultInviteTTL
	}
	if cfg.LoginFailureThreshold <= 0 {
		cfg.LoginFailureThreshold = defaultLoginFailureThreshold
	}
	if cfg.LoginLockDuration <= 0 {
		cfg.LoginLockDuration = defaultLoginLockDuration
